/* t(key, n?) — مع دعم صيغ الجمع {one,many} */
export const tr = (lang, key, n) => {
  const table = STR[lang] || STR.ar;
  const v = table[key] ?? STR.ar[key] ?? key;
  if (v && typeof v === 'object') return n === 1 ? v.one : v.many;
  return v;
};

