/* tp(key, {a,b}, n?) — استبدال القوالب {a} {b} */
export const tpl = (lang, key, map, n) => {
  let s = tr(lang, key, n);
  if (map) Object.entries(map).forEach(([a, b]) => { s = String(s).replace('{' + a + '}', b); });
  return s;
};

